import{describe,it,expect}from"vitest";import{execFileSync}from"node:child_process";import fs from"node:fs";import path from"node:path";const LAYOUT=fs.readFileSync("scripts/layout.html","utf8"),GENERATED_DIR="dist/states",pages=fs.readdirSync("dist/states").filter(t=>t.endsWith(".html"));describe("page layout template",()=>{it("applies the theme class to body, matching the CSS selectors",()=>{expect(LAYOUT).toMatch(/document\.body\.classList\.add\('light-theme'\)/),expect(LAYOUT).not.toMatch(/document\.documentElement\.classList\.add\('light-theme'\)/)}),it("runs the theme bootstrap after <body> so document.body exists",()=>{const t=LAYOUT.search(/document\.body\.classList\.add\('light-theme'\)/),e=LAYOUT.search(/<body[\s>]/i);expect(t).toBeGreaterThan(e)}),it("sets a Content-Security-Policy",()=>{expect(LAYOUT).toMatch(/http-equiv="Content-Security-Policy"/)})}),describe("generated state pages",()=>{it("generates a page per state",()=>{expect(pages.length).toBeGreaterThan(0)}),it("escapes HTML metacharacters from the data source",()=>{const t=pages.map(t=>fs.readFileSync(path.join("dist/states",t),"utf8")).filter(t=>/Machher Jhol/.test(t));expect(t.length).toBeGreaterThan(0);for(const e of t)expect(e).toMatch(/Machher Jhol &amp; Rasgulla/)}),it("carries the shared chrome on every page",()=>{for(const t of pages){const e=fs.readFileSync(path.join("dist/states",t),"utf8");expect(e,t).toMatch(/<header class="navbar"/),expect(e,t).toMatch(/<footer class="footer">/),expect(e,t).toMatch(/http-equiv="Content-Security-Policy"/)}}),it("leaves no unsubstituted template placeholders",()=>{for(const t of pages){const e=fs.readFileSync(path.join("dist/states",t),"utf8");expect(e.match(/\{\{\w+\}\}/g),t).toBeNull()}}),it("is in sync with the current layout",()=>{expect(()=>execFileSync("node",["scripts/generate.cjs","--check"])).not.toThrow()})});